import React,{useState} from 'react';
export default function FactoryReportSignIn({onSignedIn}){
 const [code,C]=useState(''),[busy,B]=useState(false),[error,E]=useState('');
 async function signIn(event){event.preventDefault();B(true);E('');try{const response=await fetch('/api/auth',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Sign-in failed.');C('');window.dispatchEvent(new Event('yai-session-changed'));await onSignedIn?.();}catch(cause){E(cause.message||'Sign-in could not be completed.');}finally{C('');B(false);}}
 return <details className="qs-card"><summary style={{cursor:'pointer',fontWeight:750}}>View factory reports · sign in to Yai</summary><p>Training reports remain available below. Enter your existing Yai factory access code to load your factory’s saved reports.</p><form onSubmit={signIn} className="qs-form-grid"><label>Yai factory access code<input aria-label="Yai factory access code" type="password" autoComplete="off" value={code} onChange={e=>C(e.target.value)} required disabled={busy}/></label><div style={{alignSelf:'end'}}><button className="qs-primary" type="submit" disabled={busy||!code.trim()}>{busy?'Signing in…':'Sign in and load factory reports'}</button></div>{error&&<p className="qs-error" role="alert">{error}</p>}</form></details>;
}
