import React, { useEffect, useState } from 'react';
import { METHODS } from './knowledge';
export const WORKSPACE_KEY='yai-decoration-workspaces-v1';
const blank=()=>({items:[],events:[],setups:{}});
export function useWorkspace(){
 const [data,setData]=useState(()=>{try{const d=JSON.parse(localStorage.getItem(WORKSPACE_KEY));return d&&Array.isArray(d.items)&&Array.isArray(d.events)&&d.setups?d:blank();}catch{return blank();}});
 const [error,setError]=useState('');
 useEffect(()=>{try{localStorage.setItem(WORKSPACE_KEY,JSON.stringify(data));setError('');}catch{setError('Setup changes could not be saved in this browser.');}},[data]);
 return {data,setData,error};
}
export function useViewer(){
 const [viewer,setViewer]=useState(null);
 useEffect(()=>{let alive=true;const load=()=>fetch('/api/auth',{credentials:'same-origin',cache:'no-store'}).then(r=>r.ok?r.json():null).then(d=>{if(alive)setViewer(d?.authenticated&&typeof d.viewer==='string'?d.viewer:null);}).catch(()=>{});load();window.addEventListener('focus',load);window.addEventListener('yai-session-changed',load);return()=>{alive=false;window.removeEventListener('focus',load);window.removeEventListener('yai-session-changed',load);};},[]);
 return viewer;
}
const Field=({label,children})=><label className="deco-field"><span>{label}</span>{children}</label>;
export const defaultSetup=()=>({sop:'DEMO-DEC-SOP-R01',frequency:60,assignment:'Area Quality Leader · named YHR assignment required',evidence:'Demo setup; replace with approved factory references',revision:1});
export function ModifySetup({setup,onSave}){
 const [draft,setDraft]=useState(setup),[error,setError]=useState('');
 function save(e){e.preventDefault();if(!draft.sop.trim()||!draft.evidence.trim()||!Number.isInteger(Number(draft.frequency))||Number(draft.frequency)<1||Number(draft.frequency)>480){setError('Enter a current SOP, evidence reference and whole inspection interval from 1–480 minutes.');return;}onSave({...draft,frequency:Number(draft.frequency),revision:setup.revision+1});setError('');}
 return <section className="deco-card"><h2>Modify · module setup</h2><p>Keep the approved operating recipe on the order. This setup records the module SOP and planned inspection interval; it does not change supplier process limits or release failed work.</p><form onSubmit={save}><div className="deco-grid"><Field label="Module SOP reference"><input aria-label="Module SOP reference" value={draft.sop} onChange={e=>setDraft({...draft,sop:e.target.value})}/></Field><Field label="Planned inspection interval · minutes"><input aria-label="Inspection interval minutes" type="number" min="1" max="480" value={draft.frequency} onChange={e=>setDraft({...draft,frequency:e.target.value})}/></Field><Field label="Assignment / approval evidence"><input aria-label="Module setup evidence" value={draft.evidence} onChange={e=>setDraft({...draft,evidence:e.target.value})}/></Field><Field label="Responsible role · verify named assignment in YHR"><input readOnly value={draft.assignment}/></Field></div>{error&&<p role="alert" className="deco-error">{error}</p>}<button className="deco-primary" type="submit">Save module setup</button></form><p>Revision {setup.revision} · Changes appear in DR. Select an inspection below to review it or create a linked correction; the original evidence stays in history.</p></section>;
}
export function AddingCatalog({mode,items,onAdd,onNew}){
 const methods=Object.keys(METHODS).filter(m=>mode==='embroidery'?m==='embroidery':mode==='printing'?m!=='embroidery':true);
 const [draft,setDraft]=useState({kind:'Defect',method:methods[0],code:'',name:''}),[error,setError]=useState('');
 function add(e){e.preventDefault();const code=draft.code.trim().toUpperCase(),name=draft.name.trim();if(!/^[A-Z0-9_-]{2,24}$/.test(code)||name.length<3){setError('Use a 2–24 character code (letters, digits, _ or -) and a descriptive name.');return;}if(items.some(i=>i.kind===draft.kind&&i.method===draft.method&&i.code===code)){setError('That code already exists for this method and type.');return;}onAdd({...draft,code,name});setDraft({...draft,code:'',name:''});setError('');}
 return <section className="deco-card"><div className="deco-toolbar"><h2>Adding · inspection master data</h2><button className="deco-primary" onClick={onNew}>New inspection</button></div><p>Add a defect code or station for this module. Custom defects become available on its inspector pad; station codes can be entered in the machine / head field.</p><form onSubmit={add}><div className="deco-fields-four"><Field label="Master data type"><select aria-label="Master data type" value={draft.kind} onChange={e=>setDraft({...draft,kind:e.target.value})}><option>Defect</option><option>Station</option></select></Field><Field label="Decoration method"><select aria-label="Master data method" value={draft.method} onChange={e=>setDraft({...draft,method:e.target.value})}>{methods.map(m=><option key={m} value={m}>{METHODS[m].name}</option>)}</select></Field><Field label="Code"><input aria-label="Master data code" value={draft.code} onChange={e=>setDraft({...draft,code:e.target.value})}/></Field><Field label="Name / description"><input aria-label="Master data name" value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></Field></div>{error&&<p role="alert" className="deco-error">{error}</p>}<button className="deco-primary" type="submit">Add master item</button></form><div className="deco-table-scroll"><table><thead><tr><th>Type</th><th>Method</th><th>Code</th><th>Name</th><th>Added</th></tr></thead><tbody>{items.map(i=><tr key={i.id}><td>{i.kind}</td><td>{METHODS[i.method]?.name}</td><td>{i.code}</td><td>{i.name}</td><td>{new Date(i.at).toLocaleString()}</td></tr>)}</tbody></table>{!items.length&&<p>The manufacturer-based defect library is already on the pad. New custom items will appear here.</p>}</div></section>;
}
export function DRHistory({records,events,onView}){
 const [day,setDay]=useState('');
 const timeline=[...events,...records.flatMap(r=>[{id:r.id,at:r.createdAt,type:r.parentId?'Reinspection':'Submission',actor:r.inspector,detail:`${r.id} · ${r.status}`,record:r},...(r.reviews||[]).map((v,i)=>({id:`${r.id}-review-${i}`,at:v.at,type:'Review',actor:v.reviewer,detail:`${r.id} · ${v.decision}`,record:r}))])].filter(e=>!day||new Date(e.at).toLocaleDateString('en-CA')===day).sort((a,b)=>b.at-a.at);
 return <section className="deco-card"><div className="deco-toolbar"><h2>DR · submission and change history</h2><Field label="Filter date"><input aria-label="DR date" type="date" value={day} onChange={e=>setDay(e.target.value)}/></Field><button className="deco-secondary" onClick={()=>setDay('')}>All dates</button></div><div className="deco-table-scroll"><table><thead><tr><th>When</th><th>Event</th><th>By</th><th>Record / change</th><th>View</th></tr></thead><tbody>{timeline.map(e=><tr key={e.id}><td>{new Date(e.at).toLocaleString()}</td><td>{e.type}</td><td>{e.actor||'Demo session'}</td><td>{e.detail}</td><td>{e.record?<button className="deco-secondary" onClick={()=>onView(e.record)} aria-label={`Open DR ${e.id}`}>View record</button>:'Setup event'}</td></tr>)}</tbody></table>{!timeline.length&&<p>No events for the selected date.</p>}</div></section>;
}
export function VideoTraining({mode}){
 const showPrint=mode!=='embroidery',showEmb=mode!=='printing';
 return <div className="deco-video-training"><h3>Manufacturer video training</h3><p>These are supplier training resources. Use the approved product sheet and factory SOP for actual temperature, time, pressure, fabric and testing requirements.</p>{showPrint&&<section className="deco-card"><h3>Heat-transfer application · Siser</h3><iframe title="Siser heat press training video" src="https://www.youtube-nocookie.com/embed/aWD8MfgLVhk" allow="fullscreen; picture-in-picture" allowFullScreen style={{width:'100%',aspectRatio:'16/9',border:0,borderRadius:10}}/><p><a href="https://www.siserna.com/siser-craft-heat-press-tips/" target="_blank" rel="noreferrer">Official Siser video and application notes ↗</a></p><p>Check pressure, platen contact and the correct material recipe. This video is for heat transfer; it is not a universal screen-print or DTG cure recipe.</p></section>}{showEmb&&<section className="deco-card"><h3>Embroidery · Madeira official training videos</h3><p>Thread, backing, hooping and setup videos from the manufacturer. Inspect both sides and check distortion after unhooping.</p><a className="deco-secondary" href="https://www.youtube.com/channel/UC5GpUBsBxFOPX020BimErhg" target="_blank" rel="noreferrer">Watch Madeira manufacturer videos ↗</a><p><a href="https://www.madeirausa.com/services/" target="_blank" rel="noreferrer">Madeira training catalogue and troubleshooting ↗</a></p></section>}<p>Use document Training for the full method-specific inspection checks and public reference library.</p></div>;
}
